{"function":"() => {
const q = s => [...document.querySelectorAll(s)];
const out = {};
out.chips = q('pnip-filter-panel .br-tag').map(e => ({text: e.textContent.trim(), tabindex: e.getAttribute('tabindex'), role: e.getAttribute('role'), focusable: e.tabIndex}));
out.avatar = (()=>{const e=document.querySelector('.content'); const cs=getComputedStyle(e); return {fs: cs.fontSize, fw: cs.fontWeight, ariaHidden: e.closest('[aria-hidden]')?.outerHTML.slice(0,100), parent: e.parentElement.outerHTML.slice(0,400)}})();
out.tabs = q('nav[aria-label="Abas de Navegação Simples"]')[0]?.outerHTML.slice(0,1500);
out.breadcrumb = document.querySelector('.br-breadcrumb, [class*=breadcrumb]')?.outerHTML.slice(0,1200);
out.pagin = q('nav[aria-label="Paginação de resultados"]')[0]?.outerHTML.slice(0,2000);
out.headings = q('h1,h2,h3,h4,h5,h6').map(h=>h.tagName+':'+h.textContent.trim());
out.landmarks = q('header,main,nav,footer,[role=banner],[role=main],[role=navigation],[role=contentinfo]').map(e=>e.tagName+'|'+(e.getAttribute('role')||'')+'|'+(e.getAttribute('aria-label')||''));
out.skip = q('a[href^="#"]').map(a=>a.outerHTML.slice(0,150));
out.header = document.querySelector('header')?.outerHTML.slice(0,1500);
return out;
}"}

